lemma hasDerivAt_comp_sqrt {f f' : ℝ → ℝ} (hf : ∀ r, 0 < r → HasDerivAt f (f' r) r) {s : ℝ}
    (hs : 0 < s) :
    HasDerivAt (fun s => f (Real.sqrt s)) (f' (Real.sqrt s) / (2 * Real.sqrt s)) s

lemma hasDerivAt_comp_sqrt' {f' f'' : ℝ → ℝ} (hf : ∀ r, 0 < r → HasDerivAt f' (f'' r) r) {s : ℝ}
